"""Run-time dimension of supply (notes 21.42): which averaging window of price / own cost does each fuel's daily output follow? And the 2-D
surface: output against today's price / cost and its 4-week mean. M1 costs; all days of the fitting period and the held-out year."""
import numpy as np, pandas as pd, warnings; warnings.filterwarnings("ignore")
import matplotlib; matplotlib.use("Agg"); import matplotlib.pyplot as plt
from scipy.stats import spearmanr
SP = "/tmp/claude-0/-home-user-EpexPredictor/d6125cc0-c431-5b93-a06f-0110cd871ab6/scratchpad"; BLUE, ORANGE, AQUA, INK, MUTED, SURF, GRID, NEUT = "#2a78d6", "#eb6834", "#1baf7a", "#0b0b0b", "#52514e", "#fcfcfb", "#e9e8e3", "#a8a79f"
plt.rcParams.update({"font.size": 9, "axes.edgecolor": "#c9c8c2", "axes.labelcolor": MUTED, "xtick.color": MUTED, "ytick.color": MUTED, "figure.facecolor": SURF, "axes.facecolor": SURF, "savefig.facecolor": SURF, "font.family": "DejaVu Sans"})
def fin(ax, t, grid=True):
    ax.grid(grid, color=GRID, linewidth=0.6); ax.set_axisbelow(True); [ax.spines[s].set_visible(False) for s in ("top", "right")]; ax.set_title(t, loc="left", fontsize=9.3, fontweight="bold", color=INK)
R = pd.read_parquet(f"{SP}/out/market1_rows.parquet"); day = R.index.normalize(); D = R.groupby(day).agg(lig=("lig", "mean"), coal=("coal", "mean"), gasg=("gasg", "mean"), rc_l=("rc_l", "mean"), rc_c=("rc_c", "mean"), rc_g=("rc_g", "mean"), n=("p", "size")); D = D[D.n >= 20].asfreq("D"); FU = (("l", "lig", "Lignite", BLUE), ("c", "coal", "Hard coal", ORANGE), ("g", "gasg", "Gas", AQUA)); WS = (1, 2, 3, 5, 7, 10, 14, 21, 28, 42, 56)
fig, axs = plt.subplots(1, 4, figsize=(19.5, 4.9), gridspec_kw=dict(wspace=0.3)); ax = axs[0]; best = {}
for f, q, nm, col in FU:
    r2 = []
    for W in WS: x = D[f"rc_{f}"].rolling(W, min_periods=max(1, int(0.7 * W))).mean(); m = x.notna() & D[q].notna(); r2.append(spearmanr(x[m], D[q][m])[0] ** 2)
    x1 = D[f"rc_{f}"]; xb = D[f"rc_{f}"].rolling(28, min_periods=20).mean(); m = x1.notna() & xb.notna() & D[q].notna(); X = np.column_stack([x1[m], xb[m], np.ones(m.sum())]); y = D[q][m].values; be = np.linalg.lstsq(X, y, rcond=None)[0]; r2b = 1 - np.var(y - X @ be) / np.var(y); r21 = np.corrcoef(x1[m], y)[0, 1] ** 2; r228 = np.corrcoef(xb[m], y)[0, 1] ** 2
    best[f] = (WS[int(np.argmax(r2))], max(r2), r2[0], r21, r228, r2b, be[0], be[1]); ax.plot(WS, r2, "-o", color=col, linewidth=1.9, markersize=4, label=f"{nm}: best at {best[f][0]} days"); print(f"{nm}: rank-correlation^2 of daily output with the W-day mean price / cost: " + " ".join(f"{W}:{v:.2f}" for W, v in zip(WS, r2)) + f" | linear R2: today {r21:.2f}, 28-day mean {r228:.2f}, both {r2b:.2f} (GW per unit: today {be[0]:+.1f}, 28-day {be[1]:+.1f})")
ax.set_xscale("log"); ax.set_xticks(WS); ax.set_xticklabels([str(w) for w in WS]); ax.set_ylim(0, 1); ax.set_xlabel("days over which price / own cost is averaged (trailing)"); ax.set_ylabel("share of the ordering of daily output explained"); ax.legend(frameon=False, fontsize=8, loc="lower left"); fin(ax, "Which average of the price does each fuel follow?\n" + ", ".join(f"{nm.lower()} {best[f][0]} d" for f, q, nm, col in FU))
for i, (f, q, nm, col) in enumerate(FU):
    ax = axs[i + 1]; x1 = D[f"rc_{f}"]; xb = D[f"rc_{f}"].rolling(28, min_periods=20).mean(); m = x1.notna() & xb.notna() & D[q].notna(); e1 = np.quantile(x1[m], np.linspace(0, 1, 6)); eb = np.quantile(xb[m], np.linspace(0, 1, 6)); b1 = np.clip(np.digitize(x1[m], e1) - 1, 0, 4); bb = np.clip(np.digitize(xb[m], eb) - 1, 0, 4); Z = np.array([[D[q][m].values[(b1 == a) & (bb == b)].mean() if ((b1 == a) & (bb == b)).sum() >= 6 else np.nan for a in range(5)] for b in range(5)])
    im = ax.imshow(Z, origin="lower", cmap="Blues", aspect="auto"); [ax.text(a, b, f"{Z[b, a]:.1f}", ha="center", va="center", fontsize=8, color=INK if Z[b, a] < np.nanmean(Z) else "white") for a in range(5) for b in range(5) if not np.isnan(Z[b, a])]
    ax.set_xticks(range(5)); ax.set_xticklabels([f"{0.5 * (e1[k] + e1[k + 1]):.2f}" for k in range(5)]); ax.set_yticks(range(5)); ax.set_yticklabels([f"{0.5 * (eb[k] + eb[k + 1]):.2f}" for k in range(5)]); ax.set_xlabel("today's price / own cost (fifths)"); ax.set_ylabel("4-week mean price / own cost (fifths)")
    row = np.nanmean(np.nanmax(Z, 1) - np.nanmin(Z, 1)); colr = np.nanmean(np.nanmax(Z, 0) - np.nanmin(Z, 0)); fin(ax, f"{nm}, GW: across today's price {row:.1f} GW,\nacross the 4-week mean {colr:.1f} GW", grid=False); best[f] += (row, colr)
fig.suptitle("The run-time dimension of supply: daily output of each fuel against averages of price / own cost over different lengths, and as a surface over today's price and the 4-week mean", x=0.125, ha="left", fontsize=10.5, fontweight="bold", color=INK, y=1.04); fig.savefig(f"{SP}/out/runtime_look.png", dpi=100, bbox_inches="tight"); print("figure ok")
